<script setup lang="ts">import {ref,watch,onMounted} from 'vue';const p=withDefaults(defineProps<{modelValue?:string;label?:string;disabled?:boolean}>(),{modelValue:''});const emit=defineEmits<{'update:modelValue':[value:string]}>();const area=ref<HTMLDivElement|null>(null);const source=ref(false);const raw=ref(p.modelValue);watch(()=>p.modelValue,v=>{if(v!==raw.value){raw.value=v||'';if(area.value&&area.value.innerHTML!==raw.value)area.value.innerHTML=raw.value}});onMounted(()=>{if(area.value)area.value.innerHTML=raw.value});function changed(){if(area.value){raw.value=area.value.innerHTML;emit('update:modelValue',raw.value)}}function insert(tag:string){if(p.disabled)return;const selection=window.getSelection();if(!selection?.rangeCount||!area.value?.contains(selection.anchorNode))return;const range=selection.getRangeAt(0);const node=document.createElement(tag);node.textContent=range.toString()||'text';range.deleteContents();range.insertNode(node);changed()}</script><template><div class="vx-rte"><span v-if="label" class="vx-field__label">{{label}}</span><div class="vx-rte__toolbar" aria-label="Formatting toolbar"><button v-for="x in [{label:'Bold',tag:'strong'},{label:'Italic',tag:'em'},{label:'Underline',tag:'u'}]" :key="x.tag" type="button" :disabled="disabled" @mousedown.prevent @click="insert(x.tag)">{{x.label}}</button><button type="button" @click="source=!source">{{source?'Visual':'HTML'}}</button></div><textarea v-if="source" class="vx-control" :disabled="disabled" :value="raw" @input="raw=($event.target as HTMLTextAreaElement).value;emit('update:modelValue',raw)"/><div v-else ref="area" class="vx-rte__surface" :contenteditable="!disabled" role="textbox" aria-multiline="true" :aria-label="label||'Rich text'" @input="changed"/></div></template>
